 "content": "def transform(grid):
    """Fill between aligned marker cells with color 3."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    markers = {value for value in counts if value != background}
    marker = max(markers, key=lambda value: counts[value]) if markers else None
    out = [row[:] for row in grid]
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 2:
            for c in range(cols[0] + 1, cols[-1]):
                if grid[r][c] != marker:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 2:
            for r in range(rows[0] + 1, rows[-1]):
                if grid[r][c] != marker:
                    out[r][c] = 3
    return out
